export function applyResizeEnd(
  start: Date,
  end: Date,
  target: Date,
): { start: Date; end: Date } | null {
  const newEnd = endOfDay(target)
  if (newEnd.getTime() <= start.getTime()) return null
  return { start: new Date(start), end: newEnd }
}

